/**
 * The single place this app registers its offline service worker.
 *
 * Registration is refused in development, inside Lovable preview/iframe
 * contexts, and when the URL contains `?sw=off`. In a refused context any
 * matching app registration is removed so a stale worker cannot keep serving
 * old files. The worker itself is generated by vite-plugin-pwa at build time.
 */

const SW_URL = "/sw.js";

const REFUSED_SUFFIXES = [
  ".lovableproject.com",
  ".lovableproject-dev.com",
  ".beta.lovable.dev",
];
const REFUSED_HOSTS = ["lovableproject.com", "lovableproject-dev.com", "beta.lovable.dev"];

const PREVIEW_HOST_SUFFIXES = [".lovable.app", ".gpt-eng.com", ".gptengineer.run"];
const PREVIEW_LABEL = /^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+$/;
const DRAFT_LABEL = /^project--[^.]+-dev$/;

function isRefusedHost(hostname: string): boolean {
  if (REFUSED_HOSTS.includes(hostname)) return true;
  if (REFUSED_SUFFIXES.some((suffix) => hostname.endsWith(suffix))) return true;
  if (!PREVIEW_HOST_SUFFIXES.some((suffix) => hostname.endsWith(suffix))) return false;
  const firstLabel = hostname.split(".")[0] ?? "";
  return PREVIEW_LABEL.test(firstLabel) || DRAFT_LABEL.test(firstLabel);
}

async function unregisterAppWorkers(): Promise<void> {
  if (!("serviceWorker" in navigator)) return;
  const registrations = await navigator.serviceWorker.getRegistrations();
  const appWorkers = registrations.filter((registration) =>
    [registration.active, registration.installing, registration.waiting].some(
      (worker) => worker?.scriptURL.endsWith(SW_URL),
    ),
  );
  await Promise.allSettled(appWorkers.map((registration) => registration.unregister()));
}

function shouldRefuse(): boolean {
  if (!import.meta.env.PROD) return true;
  if (window.self !== window.top) return true;
  if (new URLSearchParams(window.location.search).get("sw") === "off") return true;
  return isRefusedHost(window.location.hostname.toLowerCase());
}

export function registerAppServiceWorker(): void {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;
  if (shouldRefuse()) {
    void unregisterAppWorkers();
    return;
  }
  window.addEventListener("load", () => {
    navigator.serviceWorker.register(SW_URL, { scope: "/" }).catch(() => {
      // Offline support is an enhancement; the app still works online.
    });
  });
}
